Add a NULL check for mvchip->mvpwm before calling the PWM
suspend/resume functions.

Fixes: 757642f9a584 ("gpio: mvebu: Add limited PWM support")
Signed-off-by: Yun Zhou <yun.zhou@windriver.com>
Link: https://patch.msgid.link/20260608084334.2960803-1-yun.zhou@windriver.com
Signed-off-by: Bartosz Golaszewski <bartosz.golaszewski@oss.qualcomm.com>

Here is the root cause:
NULL pointer dereference in mvebu_pwm_suspend() and mvebu_pwm_resume() when called for GPIO banks without PWM support, because `mvchip->mvpwm` is NULL and no check is performed before accessing `mvpwm->blink_select`.

Here is the patch:

 static int mvebu_gpio_suspend(struct platform_device *pdev, pm_message_t state)
 {
 	struct mvebu_gpio_chip *mvchip = platform_get_drvdata(pdev);
 	int i;

 	regmap_read(mvchip->regs, GPIO_OUT_OFF + mvchip->offset,
 		    &mvchip->out_reg);
 	regmap_read(mvchip->regs, GPIO_IO_CONF_OFF + mvchip->offset,
 		    &mvchip->io_conf_reg);
 	regmap_read(mvchip->regs, GPIO_BLINK_EN_OFF + mvchip->offset,
 		    &mvchip->blink_en_reg);
 	regmap_read(mvchip->regs, GPIO_IN_POL_OFF + mvchip->offset,
 		    &mvchip->in_pol_reg);

 	switch (mvchip->soc_variant) {
 	case MVEBU_GPIO_SOC_VARIANT_ORION:
 	case MVEBU_GPIO_SOC_VARIANT_A8K:
 		regmap_read(mvchip->regs, GPIO_EDGE_MASK_OFF + mvchip->offset,
 			    &mvchip->edge_mask_regs[0]);
 		regmap_read(mvchip->regs, GPIO_LEVEL_MASK_OFF + mvchip->offset,
 			    &mvchip->level_mask_regs[0]);
 		break;
 	case MVEBU_GPIO_SOC_VARIANT_MV78200:
 		for (i = 0; i < 2; i++) {
 			regmap_read(mvchip->regs,
 				    GPIO_EDGE_MASK_MV78200_OFF(i),
 				    &mvchip->edge_mask_regs[i]);
 			regmap_read(mvchip->regs,
 				    GPIO_LEVEL_MASK_MV78200_OFF(i),
 				    &mvchip->level_mask_regs[i]);
 		}
 		break;
 	case MVEBU_GPIO_SOC_VARIANT_ARMADAXP:
 		for (i = 0; i < 4; i++) {
 			regmap_read(mvchip->regs,
 				    GPIO_EDGE_MASK_ARMADAXP_OFF(i),
 				    &mvchip->edge_mask_regs[i]);
 			regmap_read(mvchip->regs,
 				    GPIO_LEVEL_MASK_ARMADAXP_OFF(i),
 				    &mvchip->level_mask_regs[i]);
 		}
 		break;
 	default:
 		BUG();
 	}

-	if (IS_REACHABLE(CONFIG_PWM))
+	if (IS_REACHABLE(CONFIG_PWM) && mvchip->mvpwm)
 		mvebu_pwm_suspend(mvchip);

 	return 0;
 }

 static int mvebu_gpio_resume(struct platform_device *pdev)
 {
 	struct mvebu_gpio_chip *mvchip = platform_get_drvdata(pdev);
 	int i;

 	regmap_write(mvchip->regs, GPIO_OUT_OFF + mvchip->offset,
 		     mvchip->out_reg);
 	regmap_write(mvchip->regs, GPIO_IO_CONF_OFF + mvchip->offset,
 		     mvchip->io_conf_reg);
 	regmap_write(mvchip->regs, GPIO_BLINK_EN_OFF + mvchip->offset,
 		     mvchip->blink_en_reg);
 	regmap_write(mvchip->regs, GPIO_IN_POL_OFF + mvchip->offset,
 		     mvchip->in_pol_reg);

 	switch (mvchip->soc_variant) {
 	case MVEBU_GPIO_SOC_VARIANT_ORION:
 	case MVEBU_GPIO_SOC_VARIANT_A8K:
 		regmap_write(mvchip->regs, GPIO_EDGE_MASK_OFF + mvchip->offset,
 			     mvchip->edge_mask_regs[0]);
 		regmap_write(mvchip->regs, GPIO_LEVEL_MASK_OFF + mvchip->offset,
 			     mvchip->level_mask_regs[0]);
 		break;
 	case MVEBU_GPIO_SOC_VARIANT_MV78200:
 		for (i = 0; i < 2; i++) {
 			regmap_write(mvchip->regs,
 				     GPIO_EDGE_MASK_MV78200_OFF(i),
 				     mvchip->edge_mask_regs[i]);
 			regmap_write(mvchip->regs,
 				     GPIO_LEVEL_MASK_MV78200_OFF(i),
 				     mvchip->level_mask_regs[i]);
 		}
 		break;
 	case MVEBU_GPIO_SOC_VARIANT_ARMADAXP:
 		for (i = 0; i < 4; i++) {
 			regmap_write(mvchip->regs,
 				     GPIO_EDGE_MASK_ARMADAXP_OFF(i),
 				     mvchip->edge_mask_regs[i]);
 			regmap_write(mvchip->regs,
 				     GPIO_LEVEL_MASK_ARMADAXP_OFF(i),
 				     mvchip->level_mask_regs[i]);
 		}
 		break;
 	default:
 		BUG();
 	}

-	if (IS_REACHABLE(CONFIG_PWM))
+	if (IS_REACHABLE(CONFIG_PWM) && mvchip->mvpwm)
 		mvebu_pwm_resume(mvchip);

 	return 0;
 }



